Here is the commit message:
wifi: iwlwifi: assign phy_ctxt before eSR activation

eSR is activated when a chanctx is assigned to more than one link.
During eSR activation we should disable RLC for both phys, and configure
the FW with a special phy command for both phys.
Currently we assign the phy_ctxt to the link only after eSR activation,
so RLC is not disabled for the new phy_ctxt, and a cmd is not sent to FW.
Fix this by first assigning the new phy_ctxt to the link and then
doing the eSR activation.

Fixes: 12bacfc2c065 ("wifi: iwlwifi: handle eSR transitions")
Reviewed-by: Gregory Greenman <gregory.greenman@intel.com>
Signed-off-by: Miri Korenblit <miriam.rachel.korenblit@intel.com>
Link: https://msgid.link/20231219215605.3d94507f5d9a.I537fcd73aedf94c7348c03157e486f24301fef14@changeid
Signed-off-by: Johannes Berg <johannes.berg@intel.com>

Here is the root cause:
The bug was caused by the assignment of `phy_ctxt` to the link occurring after the activation of eSR, which resulted in RLC not being disabled for the new `phy_ctxt` and the firmware not receiving the necessary command for configuration. This improper sequence led to issues when a channel context was assigned to multiple links during eSR activation.

Here is the patch:

 static int
 __iwl_mvm_mld_assign_vif_chanctx(struct iwl_mvm *mvm,
 				 struct ieee80211_vif *vif,
 				 struct ieee80211_bss_conf *link_conf,
 				 struct ieee80211_chanctx_conf *ctx,
 				 bool switching_chanctx)
 {
 	u16 *phy_ctxt_id = (u16 *)ctx->drv_priv;
 	struct iwl_mvm_phy_ctxt *phy_ctxt = &mvm->phy_ctxts[*phy_ctxt_id];
 	unsigned int n_active = iwl_mvm_mld_count_active_links(vif);
 	struct iwl_mvm_vif *mvmvif = iwl_mvm_vif_from_mac80211(vif);
 	unsigned int link_id = link_conf->link_id;
 	int ret;

 	/* if the assigned one was not counted yet, count it now */
 	if (!rcu_access_pointer(link_conf->chanctx_conf))
 		n_active++;

 	if (n_active > iwl_mvm_max_active_links(mvm, vif))
 		return -EOPNOTSUPP;

 	if (WARN_ON_ONCE(!mvmvif->link[link_id]))
 		return -EINVAL;

 	/* mac parameters such as HE support can change at this stage
 	 * For sta, need first to configure correct state from drv_sta_state
 	 * and only after that update mac config.
 	 */
 	if (vif->type == NL80211_IFTYPE_AP) {
 		ret = iwl_mvm_mld_mac_ctxt_changed(mvm, vif, false);
 		if (ret) {
 			IWL_ERR(mvm, "failed to update MAC %pM\n", vif->addr);
 			return -EINVAL;
 		}
 	}

+	mvmvif->link[link_id]->phy_ctxt = phy_ctxt;
+
 	if (iwl_mvm_is_esr_supported(mvm->fwrt.trans) && n_active > 1) {
 		mvmvif->link[link_id]->listen_lmac = true;
 		ret = iwl_mvm_esr_mode_active(mvm, vif);
 		if (ret) {
 			IWL_ERR(mvm, "failed to activate ESR mode (%d)\n", ret);
-			return ret;
+			goto out;
 		}
 	}

-	mvmvif->link[link_id]->phy_ctxt = phy_ctxt;
-
 	if (switching_chanctx) {
 		/* reactivate if we turned this off during channel switch */
 		if (vif->type == NL80211_IFTYPE_AP)
 			mvmvif->ap_ibss_active = true;
 	}

 	/* send it first with phy context ID */
 	ret = iwl_mvm_link_changed(mvm, vif, link_conf, 0, false);
 	if (ret)
 		goto out;

 	/* Initialize rate control for the AP station, since we might be
 	 * doing a link switch here - we cannot initialize it before since
 	 * this needs the phy context assigned (and in FW?), and we cannot
 	 * do it later because it needs to be initialized as soon as we're
 	 * able to TX on the link, i.e. when active.
 	 *
 	 * Firmware restart isn't quite correct yet for MLO, but we don't
 	 * need to do it in that case anyway since it will happen from the
 	 * normal station state callback.
 	 */
 	if (mvmvif->ap_sta &&
 	    !test_bit(IWL_MVM_STATUS_IN_HW_RESTART, &mvm->status)) {
 		struct ieee80211_link_sta *link_sta;

 		rcu_read_lock();
 		link_sta = rcu_dereference(mvmvif->ap_sta->link[link_id]);

 		if (!WARN_ON_ONCE(!link_sta))
 			iwl_mvm_rs_rate_init(mvm, vif, mvmvif->ap_sta,
 					     link_conf, link_sta,
 					     phy_ctxt->channel->band);
 		rcu_read_unlock();
 	}

 	/* then activate */
 	ret = iwl_mvm_link_changed(mvm, vif, link_conf,
 				   LINK_CONTEXT_MODIFY_ACTIVE |
 				   LINK_CONTEXT_MODIFY_RATES_INFO,
 				   true);
 	if (ret)
 		goto out;

 	/*
 	 * Power state must be updated before quotas,
 	 * otherwise fw will complain.
 	 */
 	iwl_mvm_power_update_mac(mvm);

 	if (vif->type == NL80211_IFTYPE_MONITOR) {
 		ret = iwl_mvm_mld_add_snif_sta(mvm, vif, link_conf);
 		if (ret)
 			goto deactivate;
 	}

 	return 0;

 deactivate:
 	iwl_mvm_link_changed(mvm, vif, link_conf, LINK_CONTEXT_MODIFY_ACTIVE,
 			     false);
 out:
 	mvmvif->link[link_id]->phy_ctxt = NULL;
 	iwl_mvm_power_update_mac(mvm);
 	return ret;
 }



